/* ==========================================================================
   BelleVia Anti-Joint Pain — config
   هاد الملف هو الوحيد اللي خاصك تعمّرو قبل الإطلاق.

   ما كاينة حتى قيمة مخترعة تحت: كل شي خاوي = placeholder.
   القاعدة العامة ديال الصفحة: أي معلومة ما عمّرتيهاش، الصفحة كتخبّيها
   ولا كتبيّنها بوضوح بحال [PRICE] — عمرها ما كتخترع شي حاجة بلاصتك.
   ========================================================================== */
window.BELLEVIA_CONFIG = {

  /* ── الطلبات ───────────────────────────────────────────────────────────
     رابط الـ API اللي كيتسجل فيه الطلب. الفورم كيسيفط POST بصيغة JSON:
       { productSlug, customerName, phone, city, address, quantity, source }
     وكيتسنى جواب { ok: true, orderNumber }.

     مسار نسبي عن قصد. الصفحة كتتسيرفا من نفس الـ Pages project اللي فيه
     الـ API (`functions/api/orders.ts`)، فـ `/api/orders` كيحل على نفس
     الدومين — كيخدم على `nakhwa-store.pages.dev` وعلى أي دومين مخصص من بعد
     بلا ما تبدّل هنا والو.

     ⚠ باش يخدم، خاص يكون كاين منتج فالكاطالوگ بنفس الـ productSlug اللي
     تحت، وإلا الـ API كيرجع "product_unavailable". شوف README.

     ما دام خاوي، الفورم كيدخل ل"وضع التجربة": كيبان تنبيه فوق الفورم، وأي
     إرسال كيتردّ برسالة واضحة بللي الطلب ما تسجّلش. عمرو ما كيبين نجاح كذّاب.
     ──────────────────────────────────────────────────────────────────── */
  orderApiEndpoint: '/api/orders',

  /** الـ slug ديال المنتج فالكاطالوگ. */
  productSlug: 'bellevia-anti-joint-pain',

  /** كيتسيفط فحقل "المصدر" باش تعرف الطلبات الجايّة من هاد الصفحة. */
  source: 'bellevia-anti-joint-pain',

  /* ── الثمن والعرض ──────────────────────────────────────────────────────
     حط غير الرقم (مثال: '299') وغادي تتزاد العملة أوتوماتيكياً.
     ولا كتب النص كامل (مثال: '299 درهم') وغادي يتبين كيفما كتبتيه.

     ⚠ الثمن اللي هنا خاصو يطابق ثمن المنتج فالكاطالوگ (قاعدة البيانات).
     الصفحة كتبين هاد الرقم للزبون، ولكن اللي كيتخلّص هو اللي عند الـ API —
     إلا كانو مختالفين، الزبون غادي يشوف ثمن وتوصلو فاتورة بثمن آخر.
     ──────────────────────────────────────────────────────────────────── */
  /** ثمن العلبة الوحدة. كيبان فالهيرو («ابتداءً من …») وفـ JSON-LD. */
  price: '199',
  oldPrice: '',
  offer: '',

  /** الكلمة اللي كتبان للزبون حدا الثمن. */
  currency: 'درهم',

  /** كود العملة (ISO 4217) — كيمشي غير لـ Google/schema.org، ماشي للعرض. */
  currencyCode: 'MAD',

  /* ── العروض (Packs) ────────────────────────────────────────────────────
     كل pack فيه `qty` و`price` ديال المجموع كامل (ماشي ثمن الوحدة).
     التوفير كيتحسب أوتوماتيكياً: qty × ثمن أول pack − price.
     فما تكتبش التوفير بيدك — إلا بدّلتي شي ثمن كيتصاوب وحدو.

     خاوية `[]` دابا: بلا ثمن ديال الوحدة ما كاين على أساس واش نحسبو التوفير.
     ملي تعمّر `price` فوق، زيد هنا مثلاً:
       { qty: 1, label: '1 علبة' },
       { qty: 2, label: '2 علب', price: '…' },
       { qty: 3, label: '3 علب', price: '…', badge: 'الأكثر توفيراً' },

     ⚠ مهم: الـ API عمرو ما كيقبل ثمن من الصفحة — كيحسب المجموع عندو هو.
     الأثمنة المتدرجة كتتعرّف فـ `shared/catalog.js` (جدول PACK_PRICING،
     بالسنتيم)، وخاصها تطابق اللي كتبين هنا. وملي يتزاد سطر فهاد الجدول،
     المنتج كيتباع غير فهاد الكميات — فنقّص `max` ديال #quantity فالـ HTML.
     شوف قسم «العروض (packs) والـ API» فالـ README قبل الإعلانات.
     ──────────────────────────────────────────────────────────────────── */
  packs: [],

  /* ── التوصيل والخلاص ─────────────────────────────────────────────────── */

  /** مثال: 'توصيل لجميع المدن'. خاوي = السطر ديال التوصيل ما كيبانش فبطاقة العرض. */
  delivery: 'التوصيل مجاني',

  /** true = الدفع عند الاستلام متوفر. حطها false وكيتحيد كل ذكر ليه فالصفحة. */
  cashOnDelivery: true,

  /* ── التواصل ───────────────────────────────────────────────────────────
     عمّر غير اللي عندك بالفعل. أي حقل خاوي = ما كيبانش فالصفحة.
     وإلا ما تعمّر حتى واحد، قسم "تواصل معانا" فالفوتر كيتخبّى كامل.
     ──────────────────────────────────────────────────────────────────── */

  /** رقم WhatsApp بالصيغة الدولية بلا + ولا مسافات، مثال: '2126XXXXXXXX' */
  whatsapp: '',

  /** رقم الهاتف كيفما كتبغي يبان، مثال: '06XXXXXXXX' */
  phone: '0624373714',

  /** روابط كاملة (https://…) ولا خليها خاوية. */
  social: {
    instagram: '',
    facebook: '',
    tiktok: '',
  },

  /* ── آراء الزبناء ──────────────────────────────────────────────────────
     خاوية بمعنى الصفحة ما كتبينش قسم الآراء أصلاً — وهادي هي الحالة اللي
     كتسالى بيها الصفحة. ما غاديش نكتبو آراء من عندنا: رأي مكتوب من طرف
     اللي صاوب الصفحة كيبقى مخترع مهما تصاغ.

     ملي تكون عندك آراء حقيقية، زيدهم هنا:

       { text: 'النص ديال الرأي', name: 'الاسم، المدينة', verified: true }

     · verified: true  → كيتبين بعلامة عادية ('رأي زبون').
     · بلا verified    → كيتبين بعلامة واضحة: «نموذج توضيحي — ماشي رأي زبون
                          موثّق»، وكيتزاد سطر تحت العنوان كيوضح هادشي.
                          استعملها غير باش تشوف الشكل، ماشي فالإنتاج.
     ──────────────────────────────────────────────────────────────────── */
  testimonials: [],
};
